describe('Login to Secure Area - Returning User', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should successfully log in a returning user and navigate to secure area', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in the login form
    cy.get('[data-testid="username-input"]').type('tomsmith');
    cy.get('[data-testid="password-input"]').type('SuperSecretPassword!');

    // Submit the login form
    cy.get('[data-testid="login-button"]').click();

    // Wait for the login API response
    cy.wait('@loginRequest');

    // Verify successful login redirect
    cy.url().should('include', '/secure');

    // Verify flash banner appears with success message
    cy.get('[data-testid="flash-banner"]').should('be.visible');
    cy.get('[data-testid="flash-banner"]').should('contain', 'You logged into a secure area!');

    // Verify user is now in secure area
    cy.get('[data-testid="secure-content"]').should('be.visible');
  });

  it('should handle login failure and display error message', () => {
    // Intercept the login API call with a failed response
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid credentials' }
    }).as('loginRequestFail');

    // Fill in the login form with incorrect credentials
    cy.get('[data-testid="username-input"]').type('invaliduser');
    cy.get('[data-testid="password-input"]').type('WrongPassword');

    // Submit the login form
    cy.get('[data-testid="login-button"]').click();

    // Wait for the failed login API response
    cy.wait('@loginRequestFail');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Verify user is not redirected to secure area
    cy.url().should('not.include', '/secure');

    // Verify login form is still visible for retry
    cy.get('[data-testid="username-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
  });
});
